function verticalOrder(root) {
  // Pre-order walk (left before right) records (column, depth, visit order), then sorts.
  // Among nodes of equal depth, pre-order visits them left to right, so the visit order breaks ties.
  const entries = [];
  const visit = (node, col, depth) => {
    if (!node) return;
    entries.push({ col, depth, seq: entries.length, val: node.val });
    visit(node.left, col - 1, depth + 1);
    visit(node.right, col + 1, depth + 1);
  };
  visit(root, 0, 0);
  entries.sort((a, b) => a.col - b.col || a.depth - b.depth || a.seq - b.seq);
  const result = [];
  let last = null;
  for (const e of entries) {
    if (e.col !== last) {
      result.push([]);
      last = e.col;
    }
    result[result.length - 1].push(e.val);
  }
  return result;
}

